{"summary":"修复零延时首次扫描不输出的问题：在 TON 输出基础上，对 delay=0 且 request 为 TRUE、inhibit 为 FALSE 的工况直接置 running 为 TRUE；不改变原有计时、复位及中断后重新计时的逻辑。","code":"FUNCTION_BLOCK RestartDelay
VAR_INPUT
    request : BOOL;
    inhibit : BOOL;
    delay : TIME;
END_VAR
VAR_OUTPUT
    running : BOOL;
END_VAR
VAR
    timer : TON;
END_VAR

timer(IN := request AND NOT inhibit, PT := delay);
running := timer.Q OR (request AND NOT inhibit AND (delay <= T#0ms));

END_FUNCTION_BLOCK","assumptions":[]}
